    {
      "@id": "activity:translation-field_journal_desc-2026-07-09T05:21:02.330882+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T05:21:02.330882+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-field_journal_desc",
      "@type": "prov:Entity",
      "prov:value": "Students don't just do an activity — they record it. The Field Journal is where raw observations become structured knowledge. Back at their desk, students expand their notes with extended analysis, personal reflection, and connections to what they already know. Teachers can review, respond, and promote entries to the student's permanent portfolio."
    },
    {
      "@id": "entity:target-field_journal_desc-v1",
      "@type": "prov:Entity",
      "prov:value": "Os alunos não apenas realizam uma atividade — eles registram ela. O Field Journal é onde observações brutas se tornam conhecimento estruturado. De volta à sua mesa, os alunos expandem suas anotações com análise aprofundada, reflexão pessoal e conexões com o que já sabem. Os professores podem revisar, responder e promover entradas para o portfólio permanente do aluno.",
      "generated_by": {
        "@id": "activity:translation-field_journal_desc-2026-07-09T05:21:02.330882+00:00"
      },
      "used_source": {
        "@id": "entity:source-field_journal_desc"
      }
    },
