    {
      "@id": "activity:translation-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr-2026-07-09T05:28:32.393747+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T05:28:32.393747+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
