    },
    {
      "@id": "entity:source-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr",
      "@type": "prov:Entity",
      "prov:value": "When you upload a PDF or CSV, Ollama extracts the criteria once and caches them. Re-uploading the same file skips Ollama entirely (checksum match). A different file triggers re-extraction. Pre-seeded state sets were hand-authored and are always instant. Sets expire annually — you'll see a warning near the expiry date."
    },
    {
      "@id": "entity:target-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr-v1",
      "@type": "prov:Entity",
      "prov:value": "Ao fazer o upload de um PDF ou CSV, o Ollama extrai os critérios uma vez e os armazena em cache. O mesmo arquivo reenviado pula completamente o Ollama (comparação de soma de verificação). Um arquivo diferente aciona a re-extração. Conjuntos pré-seed foram autorados manualmente e são sempre instantâneos. Os conjuntos expiram anualmente - você receberá um aviso perto da data de expiração.",
      "generated_by": {
        "@id": "activity:translation-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr-2026-07-09T05:28:32.393747+00:00"
      },
      "used_source": {
        "@id": "entity:source-pages_homeschool_homeschoolrequirementspage.when_you_upload_a_pdf_or_csv_ollama_extr"
      }
    },
