    {
      "@id": "entity:source-components_landingpage.peripateticware_began_as_a_white_paper_w",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware began as a white paper written inside McGraw-Hill Education. It argued that GPS-enabled mobile devices would transform learning — that students walking through real places, guided by structured inquiry, could learn in a way textbooks never allowed."
    },
    {
      "@id": "entity:target-components_landingpage.peripateticware_began_as_a_white_paper_w-v1",
      "@type": "prov:Entity",
      "prov:value": "O Peripateticware começou como um artigo branco escrito dentro da McGraw-Hill Education. Ele argumentava que dispositivos móveis com GPS habilitado transformariam o aprendizado - que estudantes caminhando por lugares reais, guiados por inquirição estruturada, poderiam aprender de uma forma que os livros didáticos nunca permitiram.",
      "generated_by": {
        "@id": "activity:translation-components_landingpage.peripateticware_began_as_a_white_paper_w-2026-07-09T05:28:55.115948+00:00"
