    {
      "@id": "activity:translation-team_1_bio-2026-07-09T05:36:49.339534+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T05:36:49.339534+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-team_1_bio",
      "@type": "prov:Entity",
      "prov:value": "Paul spent a decade as a teacher, four years working for edtechs, and has been experimenting with how to break learning out of books and classrooms for two decades. Peripateticware takes advantage of LLM advancements and leverages mobile technologies to allow students to learn from the world with guidance from their teachers wherever they choose to roam."
    },
    {
      "@id": "entity:target-team_1_bio-v1",
      "@type": "prov:Entity",
      "prov:value": "Paul passou uma década como professor, quatro anos trabalhando para edtechs e vem experimentando há duas décadas como sair do aprendizado dos livros e salas de aula. A Peripateticware aproveita os avanços das LLMs e utiliza tecnologias móveis para permitir que os alunos aprendam com o mundo, orientados por seus professores, onde quer que escolham ir.",
      "generated_by": {
        "@id": "activity:translation-team_1_bio-2026-07-09T05:36:49.339534+00:00"
      },
      "used_source": {
        "@id": "entity:source-team_1_bio"
      }
    },
