    {
      "@id": "entity:source-curriculumImportPage.description",
      "@type": "prov:Entity",
      "prov:value": "Upload a PDF or CSV of official state academic standards (TEKS, NGSS, Common Core, etc.). Ollama extracts each standard for review. Once saved as a global set, all teachers and homeschool parents can map their activities against these standards. Re-uploading the same file skips processing (checksum cache)."
    },
    {
      "@id": "entity:target-curriculumImportPage.description-v1",
      "@type": "prov:Entity",
      "prov:value": "Enviar um PDF ou CSV dos padrões acadêmicos oficiais do estado (TEKS, NGSS, Common Core, etc.). O Ollama extrai cada padrão para revisão. Após serem salvos como um conjunto global, todos os professores e pais que ensinam em casa podem mapear suas atividades contra esses padrões. A reenviar o mesmo arquivo, o processamento é pulado (cache de soma de verificação).",
      "generated_by": {
        "@id": "activity:translation-curriculumImportPage.description-2026-07-09T05:37:11.552288+00:00"
      },
      "used_source": {
        "@id": "entity:source-curriculumImportPage.description"
      }
    },
